// Hand-written. Not generated by Speakeasy.
package provider

import (
	"context"
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/path"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
	"github.com/hashicorp/terraform-plugin-framework/tfsdk"
	"github.com/hashicorp/terraform-plugin-framework/types"
	"github.com/hashicorp/terraform-plugin-go/tftypes"
)

// The schema distinction the whole file turns on: an attribute the user may
// set is one the provider sends back on update, so Authlete returns it
// unchanged. One Authlete owns has to stay unknown.
var absorbSchema = schema.Schema{
	Attributes: map[string]schema.Attribute{
		"settable":  schema.StringAttribute{Optional: true, Computed: true},
		"derived":   schema.StringAttribute{Computed: true},
		"edited":    schema.StringAttribute{Optional: true},
		"with_list": schema.ListAttribute{Optional: true, Computed: true, ElementType: types.StringType},
	},
}

var absorbTypes = map[string]tftypes.Type{
	"settable":  tftypes.String,
	"derived":   tftypes.String,
	"edited":    tftypes.String,
	"with_list": tftypes.List{ElementType: tftypes.String},
}

func absorbValue(settable, derived, edited, list tftypes.Value) tftypes.Value {
	return tftypes.NewValue(tftypes.Object{AttributeTypes: absorbTypes}, map[string]tftypes.Value{
		"settable":  settable,
		"derived":   derived,
		"edited":    edited,
		"with_list": list,
	})
}

func strVal(s string) tftypes.Value { return tftypes.NewValue(tftypes.String, s) }
func strNull() tftypes.Value        { return tftypes.NewValue(tftypes.String, nil) }
func strUnknown() tftypes.Value     { return tftypes.NewValue(tftypes.String, tftypes.UnknownValue) }
func listType() tftypes.Type        { return tftypes.List{ElementType: tftypes.String} }
func listUnknown() tftypes.Value    { return tftypes.NewValue(listType(), tftypes.UnknownValue) }
func listOf(v ...string) tftypes.Value {
	out := make([]tftypes.Value, 0, len(v))
	for _, s := range v {
		out = append(out, strVal(s))
	}
	return tftypes.NewValue(listType(), out)
}

func runAbsorb(t *testing.T, state, config, plan tftypes.Value) tftypes.Value {
	t.Helper()
	req := resource.ModifyPlanRequest{
		State:  tfsdk.State{Raw: state, Schema: absorbSchema},
		Config: tfsdk.Config{Raw: config, Schema: absorbSchema},
		Plan:   tfsdk.Plan{Raw: plan, Schema: absorbSchema},
	}
	resp := resource.ModifyPlanResponse{Plan: tfsdk.Plan{Raw: plan, Schema: absorbSchema}}
	absorbSettledUnknowns(context.Background(), req, &resp)
	return resp.Plan.Raw
}

func attrOf(t *testing.T, v tftypes.Value, name string) tftypes.Value {
	t.Helper()
	var m map[string]tftypes.Value
	if err := v.As(&m); err != nil {
		t.Fatalf("not an object: %v", err)
	}
	return m[name]
}

// Editing one attribute must not report the settable ones as unknown, and
// must still report the one Authlete derives.
func TestInventedUnknownsAreAnsweredFromState(t *testing.T) {
	state := absorbValue(strVal("stored"), strVal("server-made"), strVal("before"), listOf("a", "b"))
	config := absorbValue(strNull(), strNull(), strVal("after"), tftypes.NewValue(listType(), nil))
	plan := absorbValue(strUnknown(), strUnknown(), strVal("after"), listUnknown())

	got := runAbsorb(t, state, config, plan)

	if settable := attrOf(t, got, "settable"); !settable.Equal(strVal("stored")) {
		t.Errorf("settable = %v, want the value already in state", settable)
	}
	if list := attrOf(t, got, "with_list"); !list.Equal(listOf("a", "b")) {
		t.Errorf("with_list = %v, want the list already in state", list)
	}
	if derived := attrOf(t, got, "derived"); derived.IsKnown() {
		t.Errorf("derived = %v, want it left unknown: Authlete owns it", derived)
	}
	if edited := attrOf(t, got, "edited"); !edited.Equal(strVal("after")) {
		t.Errorf("edited = %v, want the configured value", edited)
	}
}

// An unknown that came from the configuration is a value the user asked for
// and the provider cannot see yet, such as jwks built from a key being
// created in the same run. Absorbing it would silently skip the change.
func TestUnknownFromConfigurationIsLeftAlone(t *testing.T) {
	state := absorbValue(strVal("stored"), strVal("server-made"), strVal("before"), listOf("a"))
	config := absorbValue(strUnknown(), strNull(), strVal("after"), tftypes.NewValue(listType(), nil))
	plan := absorbValue(strUnknown(), strUnknown(), strVal("after"), listUnknown())

	if settable := attrOf(t, runAbsorb(t, state, config, plan), "settable"); settable.IsKnown() {
		t.Errorf("settable = %v, want it left unknown: the configuration supplied it", settable)
	}
}

// Create has no prior state worth keeping, and a replacement deliberately
// discards the old object.
func TestAbsorbLeavesCreateAndReplacementAlone(t *testing.T) {
	config := absorbValue(strNull(), strNull(), strVal("after"), tftypes.NewValue(listType(), nil))
	plan := absorbValue(strUnknown(), strUnknown(), strVal("after"), listUnknown())

	t.Run("create", func(t *testing.T) {
		null := tftypes.NewValue(tftypes.Object{AttributeTypes: absorbTypes}, nil)
		if got := attrOf(t, runAbsorb(t, null, config, plan), "settable"); got.IsKnown() {
			t.Errorf("settable = %v, want it left unknown on create", got)
		}
	})

	t.Run("replacement", func(t *testing.T) {
		state := absorbValue(strVal("stored"), strVal("server-made"), strVal("before"), listOf("a"))
		req := resource.ModifyPlanRequest{
			State:  tfsdk.State{Raw: state, Schema: absorbSchema},
			Config: tfsdk.Config{Raw: config, Schema: absorbSchema},
			Plan:   tfsdk.Plan{Raw: plan, Schema: absorbSchema},
		}
		resp := resource.ModifyPlanResponse{
			Plan:            tfsdk.Plan{Raw: plan, Schema: absorbSchema},
			RequiresReplace: path.Paths{path.Root("settable")},
		}
		absorbSettledUnknowns(context.Background(), req, &resp)
		if got := attrOf(t, resp.Plan.Raw, "settable"); got.IsKnown() {
			t.Errorf("settable = %v, want it left unknown when the resource is replaced", got)
		}
	})
}

// Position is not identity. Adding a scope at the front of supported_scopes
// shifts every element along, so an unknown inside element 0 of the plan must
// not be answered from element 0 of prior state.
func TestNestedValuesAreNotMovedBetweenEntries(t *testing.T) {
	elem := tftypes.Object{AttributeTypes: map[string]tftypes.Type{
		"name":        tftypes.String,
		"description": tftypes.String,
	}}
	listTy := tftypes.List{ElementType: elem}
	entry := func(name string, desc tftypes.Value) tftypes.Value {
		return tftypes.NewValue(elem, map[string]tftypes.Value{
			"name": strVal(name), "description": desc,
		})
	}
	sch := schema.Schema{Attributes: map[string]schema.Attribute{
		"scopes": schema.ListNestedAttribute{
			Optional: true, Computed: true,
			NestedObject: schema.NestedAttributeObject{Attributes: map[string]schema.Attribute{
				"name":        schema.StringAttribute{Optional: true},
				"description": schema.StringAttribute{Optional: true, Computed: true},
			}},
		},
	}}
	wrap := func(v tftypes.Value) tftypes.Value {
		return tftypes.NewValue(tftypes.Object{AttributeTypes: map[string]tftypes.Type{"scopes": listTy}},
			map[string]tftypes.Value{"scopes": v})
	}

	state := wrap(tftypes.NewValue(listTy, []tftypes.Value{
		entry("openid", strVal("Authlete's own wording for openid")),
		entry("profile", strVal("Authlete's own wording for profile")),
	}))
	config := wrap(tftypes.NewValue(listTy, []tftypes.Value{
		entry("added", strNull()),
		entry("openid", strNull()),
		entry("profile", strNull()),
	}))
	plan := wrap(tftypes.NewValue(listTy, []tftypes.Value{
		entry("added", strUnknown()),
		entry("openid", strUnknown()),
		entry("profile", strUnknown()),
	}))

	req := resource.ModifyPlanRequest{
		State:  tfsdk.State{Raw: state, Schema: sch},
		Config: tfsdk.Config{Raw: config, Schema: sch},
		Plan:   tfsdk.Plan{Raw: plan, Schema: sch},
	}
	resp := resource.ModifyPlanResponse{Plan: tfsdk.Plan{Raw: plan, Schema: sch}}
	absorbSettledUnknowns(context.Background(), req, &resp)

	var top map[string]tftypes.Value
	if err := resp.Plan.Raw.As(&top); err != nil {
		t.Fatalf("plan: %v", err)
	}
	var entries []tftypes.Value
	if err := top["scopes"].As(&entries); err != nil {
		t.Fatalf("scopes: %v", err)
	}
	for i, e := range entries {
		var fields map[string]tftypes.Value
		if err := e.As(&fields); err != nil {
			t.Fatalf("entry %d: %v", i, err)
		}
		if fields["description"].IsKnown() {
			t.Errorf("entry %d description = %v, want it left unknown: an entry's position is not its identity",
				i, fields["description"])
		}
	}
}

// Authlete rebuilds these from the service when a client is written, so prior
// state is a prediction. Answering them from it stores the prediction and
// loses what the API returned.
func TestAttributesRecomputedOnWriteAreLeftAlone(t *testing.T) {
	sch := schema.Schema{Attributes: map[string]schema.Attribute{
		"custom_metadata": schema.StringAttribute{Optional: true, Computed: true},
		"settable":        schema.StringAttribute{Optional: true, Computed: true},
	}}
	types := map[string]tftypes.Type{"custom_metadata": tftypes.String, "settable": tftypes.String}
	mk := func(cm, s tftypes.Value) tftypes.Value {
		return tftypes.NewValue(tftypes.Object{AttributeTypes: types},
			map[string]tftypes.Value{"custom_metadata": cm, "settable": s})
	}

	req := resource.ModifyPlanRequest{
		State:  tfsdk.State{Raw: mk(strVal(`{"k":"v"}`), strVal("stored")), Schema: sch},
		Config: tfsdk.Config{Raw: mk(strNull(), strNull()), Schema: sch},
		Plan:   tfsdk.Plan{Raw: mk(strUnknown(), strUnknown()), Schema: sch},
	}
	resp := resource.ModifyPlanResponse{Plan: tfsdk.Plan{Raw: mk(strUnknown(), strUnknown()), Schema: sch}}
	absorbSettledUnknowns(context.Background(), req, &resp)

	if got := attrOf(t, resp.Plan.Raw, "custom_metadata"); got.IsKnown() {
		t.Errorf("custom_metadata = %v, want it left unknown: Authlete rebuilds it on write", got)
	}
	if got := attrOf(t, resp.Plan.Raw, "settable"); !got.Equal(strVal("stored")) {
		t.Errorf("settable = %v, want prior state: an ordinary setting is unaffected", got)
	}
}
